import fs from 'node:fs'
import path from 'node:path'
import { DatabaseSync } from 'node:sqlite'

const dbDir = '/home/user/tanstack-auth/data'
if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true })
}

const dbPath = path.join(dbDir, 'app.db')
export const db = new DatabaseSync(dbPath)

// Initialize schema
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    salt TEXT NOT NULL
  );
`)

db.exec(`
  CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    expires_at INTEGER NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );
`)

export interface User {
  id: number
  username: string
  password_hash: string
  salt: string
}

export interface Session {
  id: string
  user_id: number
  expires_at: number
}

import crypto from 'node:crypto'
import { db, User, Session } from './db'
import { getCookie, setCookie, deleteCookie } from '@tanstack/react-start/server'

const SESSION_COOKIE_NAME = 'session_id'
const SESSION_DURATION_MS = 1000 * 60 * 60 * 24 * 7 // 7 days

export function hashPassword(password: string): { hash: string; salt: string } {
  const salt = crypto.randomBytes(16).toString('hex')
  const hash = crypto.scryptSync(password, salt, 64).toString('hex')
  return { hash, salt }
}

export function verifyPassword(password: string, hash: string, salt: string): boolean {
  const testHash = crypto.scryptSync(password, salt, 64).toString('hex')
  return testHash === hash
}

export function createSession(userId: number): string {
  const token = crypto.randomBytes(32).toString('hex')
  const expiresAt = Date.now() + SESSION_DURATION_MS

  // Insert session into DB
  const stmt = db.prepare('INSERT INTO sessions (id, user_id, expires_at) VALUES (?, ?, ?)')
  stmt.run(token, userId, expiresAt)

  // Set HTTP-only cookie
  setCookie(SESSION_COOKIE_NAME, token, {
    httpOnly: true,
    path: '/',
    maxAge: Math.floor(SESSION_DURATION_MS / 1000),
    sameSite: 'lax',
  })

  return token
}

export function getSessionUser(): { id: number; username: string } | null {
  const token = getCookie(SESSION_COOKIE_NAME)
  if (!token) {
    return null
  }

  const stmt = db.prepare('SELECT * FROM sessions WHERE id = ?')
  const session = stmt.get(token) as Session | undefined

  if (!session) {
    return null
  }

  if (session.expires_at < Date.now()) {
    // Session expired, clean it up
    const deleteStmt = db.prepare('DELETE FROM sessions WHERE id = ?')
    deleteStmt.run(token)
    deleteCookie(SESSION_COOKIE_NAME, { path: '/' })
    return null
  }

  const userStmt = db.prepare('SELECT id, username FROM users WHERE id = ?')
  const user = userStmt.get(session.user_id) as { id: number; username: string } | undefined

  if (!user) {
    return null
  }

  return user
}

export function destroySession(): void {
  const token = getCookie(SESSION_COOKIE_NAME)
  if (token) {
    const stmt = db.prepare('DELETE FROM sessions WHERE id = ?')
    stmt.run(token)
  }
  deleteCookie(SESSION_COOKIE_NAME, { path: '/' })
}

import { createServerFn } from '@tanstack/react-start'
import { db } from './db'
import { hashPassword, verifyPassword, createSession, getSessionUser, destroySession } from './auth'

export const getCurrentUser = createServerFn({ method: 'GET' })
  .handler(async () => {
    return getSessionUser()
  })

export const registerUser = createServerFn({ method: 'POST' })
  .validator((data: any) => data as { username?: string; password?: string })
  .handler(async ({ data }) => {
    const { username, password } = data
    if (!username || !password) {
      return { success: false, error: 'Username and password are required' }
    }

    const trimmedUsername = username.trim()
    if (!trimmedUsername) {
      return { success: false, error: 'Username cannot be empty' }
    }

    // Check if user already exists
    const checkStmt = db.prepare('SELECT id FROM users WHERE username = ?')
    const existing = checkStmt.get(trimmedUsername)
    if (existing) {
      return { success: false, error: 'Username already exists' }
    }

    // Hash password and insert
    const { hash, salt } = hashPassword(password)
    try {
      const insertStmt = db.prepare('INSERT INTO users (username, password_hash, salt) VALUES (?, ?, ?)')
      const res = insertStmt.run(trimmedUsername, hash, salt)
      const userId = res.lastInsertRowid as number

      // Create session
      createSession(userId)
      return { success: true }
    } catch (err: any) {
      return { success: false, error: err.message || 'Registration failed' }
    }
  })

export const loginUser = createServerFn({ method: 'POST' })
  .validator((data: any) => data as { username?: string; password?: string })
  .handler(async ({ data }) => {
    const { username, password } = data
    if (!username || !password) {
      return { success: false, error: 'Username and password are required' }
    }

    const trimmedUsername = username.trim()
    const stmt = db.prepare('SELECT * FROM users WHERE username = ?')
    const user = stmt.get(trimmedUsername) as any
    if (!user) {
      return { success: false, error: 'Invalid username or password' }
    }

    const isValid = verifyPassword(password, user.password_hash, user.salt)
    if (!isValid) {
      return { success: false, error: 'Invalid username or password' }
    }

    // Create session
    createSession(user.id)
    return { success: true }
  })

export const logoutUser = createServerFn({ method: 'POST' })
  .handler(async () => {
    destroySession()
    return { success: true }
  })

