import http from 'node:http'
import { NodeRequest, sendNodeResponse } from 'srvx/node'
import serverBuild from './dist/server/server.js'

const port = Number(process.env.PORT) || 8791

const server = http.createServer(async (req, res) => {
  try {
    const webReq = new NodeRequest({ req, res })
    const webRes = await serverBuild.fetch(webReq)
    await sendNodeResponse(res, webRes)
  } catch (err) {
    console.error('Server Error:', err)
    if (!res.headersSent) {
      res.statusCode = 500
      res.end('Internal Server Error')
    }
  }
})

server.listen(port, () => {
  console.log(`Server listening on http://localhost:${port}`)
})

import { db } from './src/db.ts'
import { hashPassword, verifyPassword } from './src/auth.ts'

console.log('Testing DB and Auth Helpers...')

// 1. Test Password Hashing
const password = 'mySecretPassword'
const { hash, salt } = hashPassword(password)
console.log('Hash:', hash)
console.log('Salt:', salt)

const isValid = verifyPassword(password, hash, salt)
console.log('Password verification valid:', isValid)
if (!isValid) {
  throw new Error('Password verification failed!')
}

const isInvalid = verifyPassword('wrongPassword', hash, salt)
console.log('Password verification invalid test:', !isInvalid)
if (isInvalid) {
  throw new Error('Password verification should have failed but passed!')
}

// 2. Test DB insertion
db.exec('DELETE FROM users')
db.exec('DELETE FROM sessions')

const insertStmt = db.prepare('INSERT INTO users (username, password_hash, salt) VALUES (?, ?, ?)')
const res = insertStmt.run('testuser', hash, salt)
console.log('Inserted user ID:', res.lastInsertRowid)

const selectStmt = db.prepare('SELECT * FROM users WHERE username = ?')
const user = selectStmt.get('testuser')
console.log('Selected user:', user)

if (!user || user.username !== 'testuser') {
  throw new Error('User selection failed!')
}

console.log('All DB and Auth Helpers tests passed!')
